from __future__ import annotations

import sys
from pathlib import Path

from pydantic_ai.messages import ModelRequest, ModelResponse, ToolCallPart, ToolReturnPart

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import agents  # noqa: E402

CHAT = agents.AGENTS[0]


def capability(name: str) -> agents.CapabilityInfo:
    return next(cap for cap in CHAT.capabilities if cap.name == name)


def test_the_chat_agent_has_its_prompt() -> None:
    assert CHAT.name == "smash-agent"
    assert "1v1" in CHAT.instructions


def test_a_capability_has_when_it_loads_its_prompt_and_its_tools() -> None:
    smashdb = capability("smashdb")
    assert smashdb.loads == agents.DEFERRED
    assert not smashdb.builtin
    assert smashdb.about.startswith("Smash Ultimate database")
    # its instructions are built by a function that takes nothing: called, not just named
    assert "SmashDb" in smashdb.instructions
    assert "built at run time" not in smashdb.instructions
    assert [tool.name for tool in smashdb.tools] == [
        "find_character",
        "list_moves",
        "get_move_framedata",
        "query_smashdb",
    ]


def test_a_tool_has_what_the_model_is_told_about_it() -> None:
    tool = next(tool for tool in capability("smashdb").tools if tool.name == "get_move_framedata")
    assert tool.about.startswith("Get frame data")
    assert [(param["name"], param["type"], param["need"]) for param in tool.params] == [
        ("character", "string", "required"),
        ("move", "string", "required"),
    ]
    optional = next(tool for tool in capability("smashdb").tools if tool.name == "find_character").params[0]
    assert optional["need"] == "default ''"


def test_pydantic_ais_own_capabilities_are_marked() -> None:
    assert capability("ToolSearch").builtin
    assert not capability("ToolCallLog").builtin


def test_how_it_loads_says_what_is_hidden_in_pydantic_ais_words() -> None:
    loading = {row["label"]: row["value"] for row in CHAT.loading}
    assert loading["Agent(instructions=...)"] == "sent on every request"
    assert loading["tools available from the first request"] == "none"
    # the agent's own 7, and the app's guide (app_guide.py), added on every run
    assert "`id` and `description`" in loading["capabilities with defer_loading=True (8)"]
    assert "(15 tools in all)" in loading["hidden until loaded"]
    assert "load_capability" in loading["loading"]
    # an inline label is a turn of the same agent with its rules added and every tool hidden
    mode = {row["label"]: row["value"] for row in agents.AGENTS[1].loading}
    assert mode["runs as"].startswith("a turn of smash-agent")
    assert mode["tools"].startswith("none")


def test_the_setup_as_text_has_every_capability_and_tool() -> None:
    for cap in CHAT.capabilities:
        assert f"Capability {cap.name} ({cap.loads}" in CHAT.text
        for tool in cap.tools:
            assert f"- {tool.name}: " in CHAT.text


def test_schema_types_are_short() -> None:
    assert agents._type({"type": "array", "items": {"type": "string"}}) == "list[string]"
    assert agents._type({"anyOf": [{"type": "integer"}, {"type": "null"}]}) == "integer | null"
    assert agents._type({"enum": ["a", "b"]}) == "one of 'a', 'b'"


def test_activity_reads_loads_and_calls_from_the_history() -> None:
    history = [
        ModelResponse(
            parts=[
                ToolCallPart("load_capability", {"id": "smashdb"}, tool_call_id="1"),
                ToolCallPart("load_capability", {"id": "nope"}, tool_call_id="2"),
            ]
        ),
        ModelRequest(
            parts=[
                ToolReturnPart("load_capability", "loaded", tool_call_id="1"),
                # a refused load comes back as a retry: not loaded
                ToolReturnPart("load_capability", "No capability found", tool_call_id="2", outcome="retried"),
            ]
        ),
        ModelResponse(
            parts=[
                ToolCallPart("get_move_framedata", {"character": "mac", "move": "jab"}, tool_call_id="3"),
                ToolCallPart("get_move_framedata", {"character": "mac", "move": "fair"}, tool_call_id="4"),
                ToolCallPart("list_moves", {"character": "mac"}, tool_call_id="5"),
            ]
        ),
    ]
    loaded, calls = agents.activity(history)
    assert loaded == ["smashdb"]
    assert calls == [{"tool": "get_move_framedata", "calls": "2"}, {"tool": "list_moves", "calls": "1"}]
    assert agents.activity([]) == ([], [])
